CREATE TABLE ai_usage_quota(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`user_id` BIGINT  NOT NULL,`date` date  NOT NULL COMMENT 'Date for quota tracking',`gps_enhanced_requests` INT  NOT NULL DEFAULT 0 COMMENT 'GPS-enhanced Bedrock API calls count',`pincode_requests` INT  NOT NULL DEFAULT 0 COMMENT 'Pincode-based recommendations count',`last_reset` timestamp  NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Last quota reset timestamp',`quota_limit` INT  NOT NULL DEFAULT 20 COMMENT 'Daily GPS-enhanced request limit')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;